import{r as j,j as k,t as oe}from"./index.template-DLa9pXVo.js";import{c as le,r as ae}from"./adventure-DJxCPJbG.js";import"./pvp-arena-DAyUwjDC.js";const z=(e,t,a,s)=>e==="th"?t:e==="zh"?s:a,g=e=>{const t=Math.sin(e*127.1+311.7)*43758.5453;return t-Math.floor(t)},ie={earth:["ปี 2100 มนุษยชาติรุ่งเรืองสุดขีด แต่โลกเริ่มเล็กเกินไปสำหรับความฝัน","Year 2100. Humanity is thriving, but Earth has become too small for its dreams.","公元2100年，人类空前繁荣，但地球已容不下我们的梦想。"],factory:["เราจึงสร้างหุ่นยนต์ผู้บุกเบิก ให้ทำงานแทนมนุษย์ ก่อนที่ใครจะเหยียบดาวดวงนั้น","So we built pioneer robots to do the work in our place, before any human sets foot there.","于是我们制造先遣机器人，在人类踏足之前替我们完成一切。"],launch:["ฝูงยานพุ่งออกจากระบบสุริยะ ขนทรัพยากรกลับโลก และปักธงอาณานิคมแห่งใหม่","The fleet leaves the Solar System to bring resources home and plant the flags of new colonies.","舰队驶离太阳系，把资源运回地球，为新殖民地插上旗帜。"]},U={luma:["ลูมา — ดาวป่าเรืองแสง เต็มไปด้วยสิ่งมีชีวิตที่ไม่เคยมีใครพบ","Luma: a glowing jungle world, full of life no one has met.","卢玛——荧光丛林星球，遍布无人见过的生命。"],ferro:["เฟอร์โร — ทะเลทรายเหล็ก แร่มหาศาลที่ถูกสนิมและหอแม่เหล็กยึดไว้","Ferro: an iron desert, its ore held hostage by rust and magnet pylons.","费罗——钢铁沙漠，矿藏被锈虫与磁力塔占据。"],jovia:["โจเวีย — ดาวแก๊สยักษ์ พลังงานมหาศาลหมุนวนอยู่ใต้เมฆ","Jovia: a gas giant, with a world's worth of energy swirling under the clouds.","朱维亚——气态巨行星，云层下涌动着庞大的能量。"],kryo:["ไครโอ — โลกน้ำแข็ง ที่ซ่อนแหล่งน้ำของอาณานิคมไว้ใต้ผลึก","Kryo: an ice world that hides the colony's water beneath crystal.","克里奥——冰封星球，殖民地的水源藏在水晶之下。"],pyra:["ไพรา — เตาปฏิกรณ์ธรรมชาติ ลาวาเดือดและแกนที่ใกล้ระเบิด","Pyra: a natural reactor, boiling lava and a core close to the edge.","派拉——天然反应堆，沸腾的熔岩与濒临失控的核心。"],nexa:["เน็กซา — ซากเมืองอวกาศของอารยธรรมที่เงียบหายไป","Nexa: the wrecked city of a civilization that went silent.","内克萨——一个沉寂文明的残骸之城。"],cobalt:["แถบโคบอลต์ — ดาวเคราะห์น้อยนับพัน เต็มไปด้วยแร่หายาก","The Cobalt Belt: thousands of asteroids heavy with rare ore.","钴带——数千颗小行星，蕴藏稀有矿石。"],helios:["เฮลิออส — ดาวฤกษ์ต่างระบบ พลังงานเหลือเฟือ ถ้ายึดมันได้","Helios: a foreign sun, with limitless energy for whoever takes it.","赫利俄斯——异星恒星，谁占领它谁就拥有无尽能量。"],ashfall:["แอชฟอลล์ — ดาวที่เอเลี่ยนสร้างฐานทัพไว้เต็มพื้นผิว","Ashfall: a world the aliens have covered in military bases.","灰烬星——遍布外星军事基地的星球。"]},V={luma:["ก่อนมนุษย์จะย้ายเข้า ต้องเคลียร์สัตว์ประหลาดเรืองแสงออกจากป่านี้ให้หมด","Before people can settle, the glowing creatures of this jungle must be cleared.","在人类入住之前，必须清除这片丛林里的发光怪物。"],ferro:["รถขุดแร่ติดอยู่ที่ขอบทะเลทราย ต้องเปิดทางให้พวกเขา","The mining rigs are stuck at the desert's edge. Someone has to open the road.","采矿车队被困在沙漠边缘，必须有人打通道路。"],jovia:["เครื่องเก็บพลังงานต้องลอยเหนือเมฆ และมีสิ่งมีชีวิตพุ่งเข้าใส่มันเป็นคลื่น","The harvester must hover over the clouds, and the creatures come at it in waves.","采集器要悬浮在云海之上，而怪物会成波涌来。"],kryo:["ผลึกน้ำแข็งมีชีวิต และผู้พิทักษ์ของมันไม่ยอมให้ใครแตะน้ำ","The crystals are alive, and their warden will not let anyone near the water.","水晶是活的，它们的守卫不许任何人接近水源。"],pyra:["บ่อลาวาขวางทาง และแกนปฏิกรณ์ต้องถูกปิดก่อนมันจะระเบิดทั้งดาว","Lava pools bar the way, and the core must be shut down before it takes the planet with it.","熔岩池挡住去路，必须在核心炸毁星球之前将其关闭。"],nexa:["แผ่นพื้นไฟฟ้ายังทำงาน และผู้ควบคุมคนสุดท้ายยังตื่นอยู่","The floor plates still carry current, and the last overseer is still awake.","地板电击板仍在通电，最后的监管者还醒着。"],cobalt:["ต้องขุดแร่ให้พอ แล้วส่งแคปซูลกลับโลก เพื่อให้อาณานิคมเติบโต","Dig enough ore and launch the capsule home, so the colony can grow.","采足矿石，把货舱发射回地球，殖民地才能壮大。"],helios:["สถานีเก็บพลังงานสามจุดเรียงรายอยู่ใต้ดวงอาทิตย์ ศัตรูจะไม่ปล่อยให้ใครยึดไป","Three collector stations stand under this sun, and the enemy will not give them up.","三座能量采集站矗立在恒星之下，敌人不会拱手相让。"],ashfall:["เราจะทิ้งระเบิดนิวเคลียร์จากวงโคจรก่อน แล้วค่อยลงไปกวาดล้างส่วนที่เหลือ","First we drop nuclear warheads from orbit. Then we land and clear what is left.","先从轨道投下核弹，再降落扫荡残余的敌人。"]},Z={luma:[["เคลียร์สัตว์ประหลาดระหว่างทาง","Clear the creatures on the way","清除沿途怪物"],["ตอบคำถามที่ beacon เพื่อรับ EXP","Answer the beacons for EXP","回答信标问题获得经验"],["ล้มผู้พิทักษ์ลูมาที่ท้ายแมป","Defeat the Luma Warden at the end","击败终点的卢玛守卫"]],ferro:[["ฝ่าสนิมและหอแม่เหล็ก","Fight through rust and pylons","突破锈虫与磁力塔"],["เก็บคริสตัลเพื่ออัปเกรด","Collect crystals to upgrade","收集晶体用于升级"],["ล้มผู้พิทักษ์เหล็ก","Defeat the Iron Warden","击败钢铁守卫"]],jovia:[["ปกป้องเครื่องเก็บพลังงานให้ครบ 90 วินาที","Hold out for 90 seconds","坚守 90 秒"],["สู้กับคลื่นศัตรูที่ถาโถม","Beat back each wave","击退每一波敌人"],["ถ้าล้ม เวลานับใหม่","If you fall, the clock restarts","倒下则重新计时"]],kryo:[["ผ่านมอนสเตอร์น้ำแข็ง","Pass the ice creatures","穿过冰霜怪物"],["ระวังเกล็ดผลึก","Watch the crystal shards","小心晶体碎片"],["ล้มผู้พิทักษ์น้ำแข็ง","Defeat the Frost Warden","击败冰霜守卫"]],pyra:[["กระโดดข้ามบ่อลาวา","Jump the lava pools","跳过熔岩池"],["สู้ผ่านมอนสเตอร์เพลิง","Fight the fire creatures","击败烈焰怪物"],["ปิดแกนด้วยการล้มผู้พิทักษ์","Shut the core down: defeat its warden","击败守卫，关闭核心"]],nexa:[["กระโดดข้ามแผ่นไฟฟ้าตอนที่ติด","Jump the shock plates while live","电击板通电时跳过"],["จัดการโดรนและโกเลมเศษเหล็ก","Take down drones and golems","解决无人机与废铁魔像"],["ล้มผู้ควบคุม — มันจะโกรธเมื่อเลือดเหลือครึ่ง","Defeat the overseer: it enrages at half health","击败监管者——半血时它会狂暴"]],cobalt:[["ทุบก้อนแร่ด้วยหมัดหรือเตะ","Break ore with punches or kicks","用拳脚击碎矿石"],["เก็บให้ได้ 10 ก้อนขึ้นไป","Gather at least 10 ore","至少采集 10 块矿"],["ส่งที่แท่นขวาสุดเพื่อยิงกลับโลก","Launch it from the far-right pad","在最右平台发射回地球"]],helios:[["ยืนยึดสถานีทีละจุด จุดละ 10 วินาที","Hold each station for 10 seconds","逐一坚守采集站 10 秒"],["ป้องกันคลื่นศัตรูขณะยึด","Beat back the waves meanwhile","占领期间击退敌军"],["ยึดครบ 3 จุดเพื่อเป็นเจ้าของดวงอาทิตย์","Take all three to own the sun","占领全部三座，拥有恒星"]],ashfall:[["ปล่อยหัวรบ 3 ลูกให้โดนฐานมากที่สุด","Drop 3 warheads on as many bases as you can","用 3 枚弹头摧毁尽可能多的基地"],["ฐานที่โดนจะไม่มีทหารตอนบุก","Destroyed bases have no defenders","被摧毁的基地没有守军"],["ลงพื้นที่แล้วล้มผู้บัญชาการ","Land and defeat the commander","降落并击败指挥官"]]},r